ALTER TABLE quiz_questions ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE quizzes ALTER COLUMN id SET DEFAULT gen_random_uuid();

BEGIN;
DELETE FROM quiz_questions WHERE quiz_id IN (SELECT id FROM quizzes WHERE course_id='241c555f-fd61-4479-ad16-245572c8a5e4' AND quiz_sequence=1);
DELETE FROM quizzes WHERE course_id='241c555f-fd61-4479-ad16-245572c8a5e4' AND quiz_sequence=1;
VALUES (gen_random_uuid(), '241c555f-fd61-4479-ad16-245572c8a5e4', 'Module 1 Assessment', 'Twenty questions on the fundamentals of Agro-forestry & Fruit Processing.', 70, 30, 'module', 'beginner', 1);
COMMIT;

SELECT COUNT(*) AS questions_loaded FROM quiz_questions
WHERE quiz_id = (SELECT id FROM quizzes WHERE course_id='241c555f-fd61-4479-ad16-245572c8a5e4' AND quiz_sequence=1);
-- expect 20
